import json,pathlib,sqlite3,zlib,hashlib,re,collections,time
out=pathlib.Path(__file__).resolve().parent; base=out.parents[1]; frame=base/'m2-intake/gutenberg-complete-English-metadata-frame-v2/frame.sqlite3';result=frame.parent/'worker-result.json';h=lambda x:hashlib.sha256(x).hexdigest();t=time.monotonic()
