   r=json.loads(zlib.decompress(row[3]));excludedfamilies.add(row[4]);knownrows.append({'ebook_ID':eid,'ordinal':row[0],'frame_raw_hash':row[2],'family_component_ID':row[4],'development_kind':kind,'titles':r['titles']})
