 fm=[f for f in r['all_formats'] if f['resolved_URL']==f'https://www.gutenberg.org/ebooks/{eid}.txt.utf-8' and f['original_URL']==f['resolved_URL'] and f['MIME_values']==['text/plain; charset=utf-8'] and not f['holds'] and type(f['extent_bytes']) is int and 0<f['extent_bytes']<=2400000 and set(f['isFormatOf_URLs'])=={f'http://www.gutenberg.org/ebooks/{eid}'}]
 if len(fm)!=1:exclusions['no_single_exact_official_UTF8_metadata_format_under_cap']+=1;continue
 stratum=next(s for s in ['narrative','biography','essays','history'] if s in g)
 priority=h(('gutenberg-original-English-body-discovery-cohort-v1\n'+str(eid)).encode())
 candidates.append({'ordinal':ordinal,'ebook_ID':eid,'frame_raw_hash':rawhash,'frame_packed_hash':packedhash,'source_binding':r['source_binding'],'family_component_ID':family,'title':title,'author_names':a['names'],'stable_author_ID':a['stable_agent_ID'],'captured_author_death':deaths[0],'captured_all_roles':agents,'metadata_stratum':stratum,'all_metadata_genres':g,'LCC_proxy':lcc,'format':fm[0],'captured_rights_fields':r['rights_fields'],'priority_sha256':priority,'original_English_provenance':'UNVERIFIED: native en plus PR/PS and creator-only are conservative discovery proxies, not proof of original language. Exact original work/edition primary provenance needed.','additional_creative_contributors':'No additional contributor captured in this record; absence is not proof of absence. Body front/back matter, title page, translation/adaptation, introduction/editor notes must be inspected.','rights_disposition':'DISCOVERY_CANDIDATE_ONLY_NOT_CLEARED; metadata USA public-domain statement does not establish exact component rights in India.','acquisition_reservation_bytes':2400000})
