proposal={'status':'READ_ONLY_FINITE_BODY_DISCOVERY_PROPOSAL_AWAIT_PARENT_REVIEW_NO_ACQUISITION','input_frame':{'path':str(frame),'sha256':expected,'worker_receipt_sha256':h(result.read_bytes())},'selection_algorithm':{'version':'fixed_priority_stratified_discovery_v1','priority_formula':'SHA256(UTF8("gutenberg-original-English-body-discovery-cohort-v1\\n"+decimal ebook_ID)); ascending digest, then ebook_ID','stratum_precedence':['narrative','biography','essays','history'],'fixed_quotas':quotas,'diversity':'At most one captured primary author and one final metadata family across all20; process strata in stated precedence. Known body-development and listed metadata-diagnostic families excluded.','purpose_and_limit':'Deliberate genre-balanced exploratory cohort, not a random sample of all English Gutenberg and not an unbiased acceptance/quality estimate. No famous-title or body-quality selection. Titles are metadata only.','rules':'Exactly one resolved creator, one exact captured death<=1900, no other captured contributors, existing metadata-eligible status, no poetry/drama, PR/PS proxy, no explicit multipart/letter/translation/selection/anthology title, exact official source-bound UTF8 format<=2.4MB. No originalEnglish certification inferred.','frame_count':len(candidates),'frame_by_disjoint_stratum':dict(collections.Counter(x['metadata_stratum'] for x in candidates)),'ordered_frame_key_SHA256':h(framebytes),'cohort_frame_file_SHA256':h((out/'cohort-frame.json').read_bytes()),'filter_counts':dict(counts),'filter_exclusion_counts':dict(exclusions),'deterministic_diversity_skips_before_quota':skips},'known_development_and_diagnostic_identity_bindings':knownrows,'records':selected,'future_acquisition_profile_proposed_not_executed':{'bodies_maximum':20,'raw_body_bytes_maximum_each':2400000,'total_durable_reservation_bytes':50000000,'reservation_arithmetic':'20*2,400,000 raw bodies=48,000,000;2,000,000 reserved for headers/receipts/partial-terminal metadata. Entire output<=50,000,000. No images/HTML/EPUB/extra body versions.','single_profile_no_retry':True,'concurrent_requests_maximum':1,'minimum_seconds_between_any_requests':2,'request_timeout_seconds':60,'whole_profile_seconds':1500,'total_body_GET_attempts':20,'redirect_policy':'Do not invent direct files URLs. Start only exact selected native-format URL; at most2 redirects per body, HTTPS www.gutenberg.org/gutenberg.org only, same ebook identity, serial and paced. Count every hop and require bounded final plain UTF8 content. No unbounded following, fallback or retries.','total_physical_HTTP_requests_maximum':60,'on_any_request_failure':'Retain exact receipt and partial bytes/hash; no replacement or automatic retry. Continue at most remaining original selected IDs only if durable global profile caps remain valid. No resumed request.','preflight':'Parent dispatch, reviewed executable/code pins, durable single allocation in existing download/storage ledger; enforce global80GB download cap and local disk/processed limits, reserve weights/free-space before any network.','raw_retention':'Stream bounded local raw with SHA256, exact requested/final URLs and all status/headers, UTF8 validation, advertised versus actual byte count, fetch timestamps. Preserve PG wrapper/terms/front/backmatter in raw; no automatic body stripping.','next_gates':['Inspect complete front/back matter and exact work/edition provenance; resolve originalEnglish versus translation/adaptation using primary evidence, not en alone.','Enumerate original author body versus editors, prefaces, notes, illustrations/captions, translations, modern additions and PG packaging. Ordinary old-author term alone cannot clear every component.','Separate chapter/prose extraction proposal with offsets and source hashes; no automatic notice removal or admission.','Language/semantic/factual quality, global family/dedup/leakage and frozen fresh acceptance sample remain required.']},'requests_made':0,'bodies_acquired':0,'rights_cleared':0,'new_admitted_documents':0,'new_admitted_tokens':0}
